"""Summarize node mail without modifying its files."""
import argparse
from datetime import datetime
import json
from pathlib import Path
import re


_NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
_REQUIRED = ("id", "from", "to", "status", "at")
_RESOLVED = frozenset(("DONE", "BLOCKED", "NEEDS-USER", "FAILED"))


def _mailboxes(root):
    for box in sorted(root.iterdir(), key=lambda path: path.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_dir() and not inbox.is_symlink():
            yield box.name, inbox


def _files(inbox):
    for directory in (inbox, inbox / "done"):
        if directory.is_symlink() or not directory.is_dir():
            continue
        for path in directory.iterdir():
            if (not path.name.startswith(".") and path.suffix == ".md"
                    and not path.is_symlink() and path.is_file()):
                yield path


def _letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in _REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not _NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return (fields, at), None


def summarize(root, now):
    boxes = {}
    paths = []
    for name, inbox in _mailboxes(root):
        boxes[name] = {"inbox": {}, "done": 0}
        paths.extend(_files(inbox))
    paths.sort(key=lambda path: path.relative_to(root).as_posix())
    bad = []
    valid = []
    ids = set()
    for path in paths:
        relative = path.relative_to(root).as_posix()
        letter, why = _letter(path, now)
        if why is None:
            fields, at = letter
            if fields["id"] in ids:
                why = "dup_id"
            else:
                ids.add(fields["id"])
                where = "done" if path.parent.name == "done" else "inbox"
                valid.append((fields, at, where))
                box = boxes[path.relative_to(root).parts[0]]
                if where == "done":
                    box["done"] += 1
                else:
                    counts = box["inbox"]
                    status = fields["status"]
                    counts[status] = counts.get(status, 0) + 1
        if why is not None:
            bad.append({"file": relative, "why": why})
    resolved = {fields.get("re") for fields, _, _ in valid
                if fields["status"] in _RESOLVED and fields.get("re")}
    opened = []
    for fields, at, where in valid:
        if fields["status"] == "REQUEST" and fields["id"] not in resolved:
            opened.append({"id": fields["id"], "from": fields["from"],
                           "to": fields["to"], "where": where,
                           "age_min": int((now - at).total_seconds() // 60)})
    opened.sort(key=lambda item: (item["to"], item["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only node mailtodo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be a timezone-aware ISO datetime")
    if now.tzinfo is None:
        parser.error("--now must include a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
